function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '40px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('344', W / 2, H / 2);
  ctx.beginPath();
  ctx.arc(W / 2 - 70, H / 2 - 70, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 + 70, H / 2 - 70, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 70, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 70, H / 2 - 60);
  ctx.lineTo(W / 2 - 70, H / 2 - 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 70, H / 2 - 60);
  ctx.lineTo(W / 2 + 70, H / 2 - 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 10, H / 2 + 70);
  ctx.lineTo(W / 2 - 30, H / 2 + 90);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 10, H / 2 + 70);
  ctx.lineTo(W / 2 + 30, H / 2 + 90);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2 - 70, H / 2 - 70, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W / 2 + 70, H / 2 - 70, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 + 70, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.rotate(Math.sin(t));
  ctx.restore();
}
